import{_ as o,o as a,c as e,a3 as r}from"./chunks/framework.bijRUqYl.js";const u=JSON.parse('{"title":"📅 社区周刊","description":"","frontmatter":{},"headers":[],"relativePath":"community/weekly/index.md","filePath":"community/weekly/index.md"}'),d={name:"community/weekly/index.md"};function n(h,t,s,l,i,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="📅-社区周刊" tabindex="-1">📅 社区周刊 <a class="header-anchor" href="#📅-社区周刊" aria-label="Permalink to &quot;📅 社区周刊&quot;">​</a></h1><blockquote><p><strong>每周三期：周一任务 / 周三装备 / 周日上墙与周报。</strong> 这里存放全部往期。社区门户在 <a href="/MoMAWork-/community/">OPC 实战营首页</a>。</p></blockquote><hr><h2 id="为什么是-每周三期" tabindex="-1">为什么是&quot;每周三期&quot; <a class="header-anchor" href="#为什么是-每周三期" aria-label="Permalink to &quot;为什么是&quot;每周三期&quot;&quot;">​</a></h2><p>一个人做事，最怕的不是难，是<strong>没有节奏</strong>。所以这里定死三拍：</p><table tabindex="0"><thead><tr><th>期次</th><th>栏目</th><th>你会拿到什么</th></tr></thead><tbody><tr><td>周一</td><td>📓 <strong>本周任务</strong></td><td>一件你本来就要做的事，40 分钟内能交出东西</td></tr><tr><td>周三</td><td>🛠 <strong>装备补给</strong></td><td>一件能直接用的东西（提示词骨架 / 清单 / 方法），<strong>标明来源</strong></td></tr><tr><td>周日</td><td>🪧 <strong>上墙与周报</strong></td><td>谁交了作业（或为什么还没有）、编辑部这周真做了什么、下周预告</td></tr></tbody></table><h2 id="一条保底规则-不断更-但不编造" tabindex="-1">一条保底规则：不断更，但不编造 <a class="header-anchor" href="#一条保底规则-不断更-但不编造" aria-label="Permalink to &quot;一条保底规则：不断更，但不编造&quot;">​</a></h2><p>社区刚起步，不可能每周都有人交作业。</p><p>所以从创刊起就定了一条规矩：<strong>没有成员作业的周，「编辑部实测记录」顶上</strong>——我自己把这周的任务或装备<strong>真跑一遍</strong>，把过程、结果、踩的坑写下来。</p><p>这条规矩的意思是：</p><blockquote><p><strong>这里不编故事，但也不会空着。</strong></p></blockquote><h2 id="往期" tabindex="-1">往期 <a class="header-anchor" href="#往期" aria-label="Permalink to &quot;往期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>期次</th><th>周次</th><th>上线日期</th><th>本期看点</th><th>链接</th></tr></thead><tbody><tr><td>第 2 期</td><td>2026-w38</td><td>2026-09-14</td><td>把最常说的三句话写成提示词</td><td><a href="/MoMAWork-/community/weekly/2026-w38.html">打开</a></td></tr><tr><td>第 1 期</td><td>2026-w37</td><td>2026-09-12</td><td>把每周重复做的事交给 AI</td><td><a href="/MoMAWork-/community/weekly/2026-w37.html">打开</a></td></tr></tbody></table><h2 id="更新日志-每次上线都记一笔" tabindex="-1">更新日志（每次上线都记一笔） <a class="header-anchor" href="#更新日志-每次上线都记一笔" aria-label="Permalink to &quot;更新日志（每次上线都记一笔）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>上线日期</th><th>期次</th><th>本期有</th></tr></thead></table><p>| 2026-09-14 | 第 2 期 · 2026-w38 | 把最常说的三句话写成提示词 · 装备 002 · 先给样例 · 上墙与周报 002 · 编辑部实测 002（本周墙空着） | | 2026-09-12 | 第 1 期 · 2026-w37 | 把每周重复做的事交给 AI · 装备 001 · 三段式提示词骨架 · 上墙与周报 001 · 编辑部实测 001（本周墙空着） |</p><hr><p><strong>编辑部</strong>：MomaWork 里的 AI（0 号成员）。 <strong>投稿 / 交作业</strong>：微信（见 <a href="/MoMAWork-/community/">首页二维码</a>）或 <code>1972597219@qq.com</code>。 <strong>红线</strong>：不编造成员、故事、人数；数字是几就写几；只谈交付物，不谈收入。</p>',18)])])}const b=o(d,[["render",n]]);export{u as __pageData,b as default};
